from __future__ import annotations

__doc__ = """

The ADAA class holds data references to HPC backends and unpacks accordingly
for function calls.

Basic arithemtic operations are implemented via a mapping into a basic
linop(A, b, C) -> A + b * C operation

DContainer combines multiple Layers to a combined datatype and can be extended
to manage inter-layer data conversion, host-device sync and consistency checks.

So far, no arithmetic operation is implemented on this level, intentionally,
as, depending on the interpretation of levels, such an implementation might be
factually wrong.

"""

# pylint: disable=too-many-arguments


import warnings
import numpy as np


from phoenix.backendwrappers import CoeffBackend
from phoenix.backendwrappers import PurePyCoeffBackend
from phoenix.backendwrappers import NumpyCoeffBackend
from phoenix.backendwrappers import FortranCoeffBackend
from phoenix.backendwrappers import CupyCoeffBackend
from phoenix.backendwrappers import OpenClCoeffBackend

from phoenix.keymap import KeyMap

ZERO_TOL = 1e-14


class ADAA:
    """
    ADAA is an acronym for Aligned Data Access Array.
    This data type is intended for the systematic distribution of data into
    multiple aligned arrays. An example for this distribution are arrays
    holding the real and imaginary parts of numbers that were originally
    stored in a complex array. The distribution does not require more memory
    but might allow optimizations based on the active distinction between
    e.g. real and imaginary parts.

    The base class implements just this case and comes along with basic
    arithmetic operations.
    """

    _IDENTIFIER = "COMPLEX_ARRAY"
    BACKEND: CoeffBackend = None
    KEYMAP: KeyMap = None
    FIXED_SIZE = None

    def __init__(self, size: int = 0):
        if self.FIXED_SIZE is None and self.KEYMAP is None:
            if not size:
                raise ValueError("Size must be given or fixed.")
        if self.FIXED_SIZE:
            if size:
                raise ValueError(f"Size is fixed ({self.FIXED_SIZE})")
            size = self.FIXED_SIZE
        if self.KEYMAP:
            if size:
                raise ValueError(f"Size is fixed by keymap {self.KEYMAP}")
            size = self.KEYMAP.size
        self._size = size
        self._data_r = None
        self._data_i = None
        self.reinit(size)

    # def _set_data(self, real=None, imag=None):
    #     """Set the data."""
    #     if real is not None:
    #         self._data_r = real
    #     if imag is not None:
    #         self._data_i = imag
    #     return self

    @property
    def real(self):
        """Access protected attribute real."""
        return self._data_r

    @real.setter
    def real(self, arr):
        """Set the data for real part."""
        # self._set_data(real=arr)
        raise ValueError("Real part of the data cannot be set directly.")

    @property
    def imag(self):
        """Access protected attribute imag."""
        return self._data_i

    @imag.setter
    def imag(self, arr):
        """Set the data for imag part."""
        # self._set_data(imag=arr)
        raise ValueError("Imag part of the data cannot be set directly.")

    @property
    def identifier(self) -> str:
        """access write-protected property 'identifier'"""
        return self._IDENTIFIER

    @property
    def size(self) -> int:
        """Access write-protected property 'size'"""
        return self._size

    def to_zero(self):
        """Set the coefficient data to zero."""
        self.BACKEND.coeff_to_zero(self._data_r, size=self.size, dtype="f64")
        self.BACKEND.coeff_to_zero(self._data_i, size=self.size, dtype="f64")
        return self

    @classmethod
    def from_numpy(cls, arr: np.ndarray) -> ADAA:
        """Import data from numpy array."""
        size = len(arr)
        obj = cls(size)
        cls.BACKEND.coeff_from_numpy(
            obj.real, arr.real, size=size, dtype="f64"
        )
        cls.BACKEND.coeff_from_numpy(
            obj.imag, arr.imag, size=size, dtype="f64"
        )
        return obj

    def to_numpy(self) -> np.ndarray:
        """Export data as numpy array."""
        real_part = self.BACKEND.coeff_to_numpy(
            self.real, size=self.size, dtype="f64"
        )
        imag_part = self.BACKEND.coeff_to_numpy(
            self.imag, size=self.size, dtype="f64"
        )
        return real_part + 1j * imag_part

    def unpack(self) -> tuple:
        """Unpack the layer into a tuple to apply it to functions."""
        return (self._data_r, self._data_i, self.size)

    def copy(self) -> ADAA:
        """Creates a real copy of self."""
        copy = self.__class__(self.size)
        self.BACKEND.coeff_copy_data(
            copy.real, self.real, size=self.size, dtype="f64"
        )
        self.BACKEND.coeff_copy_data(
            copy.imag, self.imag, size=self.size, dtype="f64"
        )
        return copy

    @classmethod
    def allclose(cls, op_a, op_b, rtol=1e-05, atol=1e-8):
        """
        Check if the values are all sufficiently close by checking, if
        |a - b|² <= atol² + rtol² (|a|² + |b|²) / 4
        is fulfilled for all coefficients.
        """
        if op_a.size != op_b.size:
            raise ValueError("Compared operators must have the same size.")
        real_all_close = cls.BACKEND.coeff_allclose(
            op_a.real, op_b.real, rtol, atol, size=op_a.size, dtype="f64"
        )
        imag_all_close = cls.BACKEND.coeff_allclose(
            op_a.imag, op_b.imag, rtol, atol, size=op_a.size, dtype="f64"
        )
        return real_all_close and imag_all_close

    @classmethod
    def basic_linop(cls, op_r, /, op_a=None, sc_b=None, op_c=None, size=None):
        """returns operator_a + scalar_b * operator_c"""

        assert op_c is not None
        assert op_r is not None

        if size is None:
            size = op_r.size

        if op_a is None:
            zero = cls(size).to_zero()
            oar, oai = zero.real, zero.imag
        else:
            oar = op_a.real
            oai = op_a.imag

        ocr = op_c.real
        oci = op_c.imag

        if sc_b is None:
            sbr, sbi = (1.0, 0.0)
        else:
            sbr, sbi = (complex(sc_b).real, complex(sc_b).real)

        aux_r = cls.BACKEND.coeff_new_array(size, dtype="f64")
        aux_i = cls.BACKEND.coeff_new_array(size, dtype="f64")

        # sbr * ocr - sbi * oci -> aux_r
        cls.BACKEND.coeff_linop(
            aux_r, sbr, ocr, -1 * sbi, oci, size=size, dtype="f64"
        )
        # sbi * ocr + sbr * oci -> aux_i
        cls.BACKEND.coeff_linop(
            aux_i, sbi, ocr, sbr, oci, size=size, dtype="f64"
        )

        # bracket + oar -> op_r.real
        cls.BACKEND.coeff_add(op_r.real, aux_r, oar, size=size, dtype="f64")
        # bracket + oai -> op_r.imag
        cls.BACKEND.coeff_add(op_r.imag, aux_i, oai, size=size, dtype="f64")

    def free_memory(self):
        """free the occupied memory"""
        self._data_r = self.BACKEND.coeff_free(
            self._data_r, size=self.size, dtype="f64"
        )
        self._data_i = self.BACKEND.coeff_free(
            self._data_i, size=self.size, dtype="f64"
        )

    def _reinit(self, size=None):
        """Reinitialize the data for a certain size"""
        if size is None:
            size = self.size
        else:
            if size == self.size:
                return
        self.reinit(size)

    def reinit(self, size):
        """Actual reinitialization. Forced."""
        self.free_memory()
        self._size = size
        self._data_r = self.BACKEND.coeff_new_array(size, dtype="f64")
        self._data_i = self.BACKEND.coeff_new_array(size, dtype="f64")

    def __init_subclass__(
        cls, backend=None, identifier=None, keymap=None, size=None
    ):
        """
        When a new subclass is derived, introduce the class
        variable _IDENTIFIER.
        """
        if backend is None:
            if cls.BACKEND is None:
                raise ValueError("No backend specified.")
        else:
            cls.BACKEND = backend
        if identifier is None:
            identifier = cls.__name__  # get default
        cls._IDENTIFIER = identifier
        if size is not None and keymap is not None:
            raise ValueError("Size and keymap cannot be set simultaneously.")
        if keymap is not None:
            cls.KEYMAP = keymap  # get default
        if size is not None:
            cls.FIXED_SIZE = size

    @classmethod
    def set_keymap(cls, keymap: KeyMap) -> type:
        """derive a type with given keymap"""
        if cls.FIXED_SIZE:
            raise ValueError("Cannot set keymap when fixed size is given.")
        if cls.KEYMAP is not None:
            raise ValueError(f"KeyMap {cls.KEYMAP} already set.")
        return type(cls._IDENTIFIER + f"<{keymap}>", (cls,), {}, keymap=keymap)

    @classmethod
    def fix_size(cls, size: int) -> type:
        """derive a fixed size type"""
        if cls.KEYMAP:
            raise ValueError("Cannot derive fixed size when keymap is given.")
        if cls.FIXED_SIZE:
            raise ValueError(f"Fixed size {cls.FIXED_SIZE} already set.")
        return type(cls._IDENTIFIER + f"[{size}]", (cls,), {}, size=size)

    ###########################################################################
    #
    # MAGIC
    # =====

    def __add__(self, other):
        if isinstance(other, self.__class__):
            assert self.size == other.size
            assert self.identifier == other.identifier
            result = self.__class__(size=self.size)
            self.basic_linop(result, op_a=self, sc_b=1, op_c=other)
            return result
        raise ValueError(
            "Subtraction between operator and non-operator is not supported"
        )

    def __sub__(self, other):
        if isinstance(other, self.__class__):
            assert self.size == other.size
            assert self.identifier == other.identifier
            result = self.__class__(size=self.size)
            self.basic_linop(result, op_a=self, sc_b=-1, op_c=other)
            return result
        raise ValueError(
            "Subtraction between operator and non-operator is not supported"
        )

    def __mul__(self, other):
        if isinstance(other, ADAA):
            raise ValueError(
                "Multiplication with other operator is not supported"
            )
        result = self.__class__(size=self.size)
        self.basic_linop(result, op_a=None, sc_b=other, op_c=self)
        return result

    def __truediv__(self, other):
        if isinstance(other, ADAA):
            raise ValueError("Dividing through operator is not supported")
        result = self.__class__(size=self.size)
        inv_other = 1.0 / other
        self.basic_linop(result, op_a=None, sc_b=inv_other, op_c=self)
        return result

    def __rmul__(self, other):
        # assume commutative, because if the other operator is an ADAA as well,
        # why else should rmul be called?
        return self.__mul__(other)

    def __neg__(self):
        result = self.__class__(size=self.size)
        self.basic_linop(result, op_a=None, sc_b=-1, op_c=self)
        return result

    def __len__(self):
        return self.size

    def __bool__(self):
        return self.size > 0

    def __eq__(self, other):
        return self.__class__.allclose(
            self, other
        )  # , rtol=1e-08, atol=1e-12)

    def __del__(self):
        self.free_memory()


class DContainer:
    """DContainer class description"""

    _LAYERS: dict[str, ADAA] = {}

    def __init__(self, *sizes):
        if len(sizes) != len(self._LAYERS):
            raise ValueError("Sizes must match the number of layers")
        self._layers = {
            key: layer(size)
            for (key, layer), size in zip(self._LAYERS.items(), sizes)
        }

    def __init_subclass__(cls, **layers):
        cls._LAYERS = layers
        return cls

    def __getitem__(self, key: int | str):
        if isinstance(key, str):
            if key not in self._layers:
                raise KeyError(f"Layer '{key}' not found")
            return self._layers[key]
        elif isinstance(key, int):
            return self._layers[list(self._LAYERS.keys())[key]]
        else:
            raise TypeError("Key must be an integer or a string")

    def unpack(self, key, **kwargs):
        """unpack the requested layer"""
        assert key in self._layers
        return self._layers[key].unpack(**kwargs)

    def unpack_multi(self, keys, **kwargs):
        """unpack the requested layer"""
        for key in keys:
            assert key in self._layers
        return [self._layers[key].unpack(**kwargs) for key in keys]


class DLC(DContainer):
    """Dual Layer Container class. Implements host-device interaction"""


class SDLC(DLC):
    """Synced Dual Layer Container class"""


